CREATE TABLE IF NOT EXISTS public.roteirizacao_projetos (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, nome TEXT NOT NULL, data_operacao DATE, dados JSONB NOT NULL DEFAULT '{}'::jsonb, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.roteirizacao_projetos TO authenticated; GRANT ALL ON public.roteirizacao_projetos TO service_role; ALTER TABLE public.roteirizacao_projetos ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Equipe gerencia projetos de roteirizacao" ON public.roteirizacao_projetos; CREATE POLICY "Equipe gerencia projetos de roteirizacao" ON public.roteirizacao_projetos FOR ALL TO authenticated USING (private.is_staff(auth.uid())) WITH CHECK (private.is_staff(auth.uid())); DROP TRIGGER IF EXISTS trg_roteirizacao_projetos_updated ON public.roteirizacao_projetos; CREATE TRIGGER trg_roteirizacao_projetos_updated BEFORE UPDATE ON public.roteirizacao_projetos FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();